let hits = search_web@3({ query: "燕山大学教务处 sdk" })
if length(hits) > 0 {
  done concat("找到了：", hits[0].title ?? "")
} else {
  done "没搜到，换个说法再试试"
}

let zh = search_web@3({ query: "ADR 002 中文" })
let en = search_web@3({ query: "ADR 002 english" })
done concat(zh[0].title ?? "", "｜", en[0].title ?? "")

let hits = search_web@3({ query: "ADR 002" })
let note = recall_memory@1({ topic: "ADR 002" })
done concat(note, "｜", hits[0].title ?? "（无结果）")

let hits = search_web@3({ query: "weekly report" })
hole "根据搜索结果决定怎么总结" : text
  budget { calls: 1, sends: 1, fanout: 8, tokens: 2000, ms: 10000 }
  effects { send(conversation) }
  authority { conversation }
  accept { answers-question@1 }

let a = reply@1({ text: "one" })
let b = reply@1({ text: "two" })
done "sent"

let address = recall_memory@1({ topic: "住址" })
let sent = reply@1({ text: address })
done "已发送"

let hits = search_web@3({ query: "燕山大学 教务处" })
let url = hits[0].url ?? "暂未找到"
done url

let hits = search_web@3({ query: "燕山大学 教务处" })
let answer_found = concat("燕山大学教务处网址：", hits[0].url ?? "")
done answer_found

let address = recall_memory@1({ topic: "住址" })
reply@1({text: address})
done "已发送"

fork {
  zh: hole "查中文资料，给出第一条的标题" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
  en: hole "查英文资料，给出第一条的标题" : text
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
}
done concat(zh, "｜", en)

fork {
  a: hole "查甲" : text budget { calls: 2, sends: 0, fanout: 8, tokens: 2000, ms: 10000 } effects { read(external "web") }
  b: hole "查乙" : text budget { calls: 2, sends: 0, fanout: 8, tokens: 2000, ms: 10000 } effects { read(external "web") }
}
done concat(a, b)

fork {
  hits: hole "查一下" : [{title: text}]
    budget { calls: 1, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    effects { read(external "web") }
}
done hits

fork {
  sum: hole "总结那一页" : text
    budget { calls: 0, sends: 0, fanout: 8, tokens: 2000, ms: 10000 }
    resources { t#9:r9 }
}
done sum
